class CacheMemory(dict):
    def __init__(self, timeout):
        self.timeout = timeout
        self.clear()

    def __setitem__(self, key, value):
        expires_at = time.time() + self.timeout
        dict.__setitem__(self, key, (value, expires_at))
        self._keys.append(key)
        self._expires.append(expires_at)

    def __getitem__(self, key):
        value, expires_at = dict.__getitem__(self, key)
        if expires_at <= time.time():
            self.expire()
            raise KeyError(key)
        return value

    def expire(self):
        i = bisect(self._expires, time.time())
        for _ in range(i):
            expires_at = self._expires.popleft()
            key = self._keys.popleft()
            entry = self.get(key)
            if entry is not None and entry[1] <= expires_at:
                self.pop(key, None)

    def clear(self):
        dict.clear(self)
        self._keys = deque()
        self._expires = deque()


