"use strict"
import {
	each,
	has,
	is,
	isDraft,
	isDraftable,
	isEnumerable,
	isMap,
	isSet,
	hasSymbol,
	shallowCopy,
	DRAFT_STATE,
	latest
} from "./common"
import {proxyMap, hasMapChanges} from "./map"
import {proxySet, hasSetChanges} from "./set"

import {ImmerScope} from "./scope"
import {ImmerState, Drafted, AnyObject, AnyMap} from "./types"

// TODO: merge with ImmerState?
interface ES5BaseState {
	scope: ImmerScope
	modified: boolean
	finalizing: boolean
	finalized: boolean
	assigned: {[key: string]: any}
	parent: ImmerState
	drafts: AnyMap | null // TODO: don't use map?
	revoke()
	revoked: boolean
}

export interface ES5ObjectState extends ES5BaseState {
	type: "es5_object"
	draft: Drafted<AnyObject, ES5ObjectState>
	base: AnyObject
	copy: AnyObject | null
}

export interface ES5ArrayState extends ES5BaseState {
	type: "es5_array"
	draft: Drafted<AnyObject, ES5ArrayState>
	base: AnyObject
	copy: AnyObject | null
}

type ES5State = ES5ArrayState | ES5ObjectState

export function willFinalizeES5(
	scope: ImmerScope,
	result: any,
	isReplaced: boolean
) {
	scope.drafts!.forEach(draft => {
		draft[DRAFT_STATE].finalizing = true
	})
	if (!isReplaced) {
		if (scope.patches) {
			markChangesRecursively(scope.drafts![0])
		}
		// This is faster when we don't care about which attributes changed.
		markChangesSweep(scope.drafts)
	}
	// When a child draft is returned, look for changes.
	else if (isDraft(result) && result[DRAFT_STATE].scope === scope) {
		markChangesSweep(scope.drafts)
	}
}

export function createES5Proxy<T>(
	base: T,
	parent: ImmerState
): Drafted<any, ES5ObjectState | ES5ArrayState> {
	if (!base || typeof base !== "object" || !isDraftable(base)) {
		// TODO: || isDraft ?
		return base as any // TODO: fix
	}
	const scope = parent ? parent.scope : ImmerScope.current!
	if (isMap(base)) {
		const draft = proxyMap(base, parent) as any // TODO: typefix
		scope.drafts.push(draft)
		return draft
	}
	if (isSet(base)) {
		const draft = proxySet(base, parent) as any // TODO: typefix
		scope.drafts.push(draft)
		return draft
	}

	const isArray = Array.isArray(base)
	const draft = clonePotentialDraft(base)

	each(draft, prop => {
		proxyProperty(draft, prop, isArray || isEnumerable(base, prop))
	})

	const state: ES5ObjectState | ES5ArrayState = {
		type: isArray ? "es5_array" : ("es5_object" as any),
		scope,
		modified: false,
		finalizing: false, // es5 only
		finalized: false,
		assigned: isMap(base) ? new Map() : {},
		parent,
		base,
		draft,
		drafts: isSet(base) ? new Map() : null,
		copy: null,
		revoke,
		revoked: false // es5 only
	}

	createHiddenProperty(draft, DRAFT_STATE, state)
	scope.drafts!.push(draft)
	return draft
}

function revoke(this: ES5BaseState) {
	this.revoked = true
}

// TODO: type these methods
// Access a property without creating an Immer draft.
function peek(draft, prop) {
	const state = draft[DRAFT_STATE]
	if (state && !state.finalizing) {
		state.finalizing = true
		const value = draft[prop]
		state.finalizing = false
		return value
	}
	return draft[prop]
}

function get(state, prop) {
	assertUnrevoked(state)
	const value = peek(latest(state), prop)
	if (state.finalizing) return value
	// Create a draft if the value is unmodified.
	if (value === peek(state.base, prop) && isDraftable(value)) {
		prepareCopy(state)
		return (state.copy[prop] = createES5Proxy(value, state))
	}
	return value
}

function set(state: ES5State, prop, value) {
	assertUnrevoked(state)
	state.assigned[prop] = true
	if (!state.modified) {
		if (is(value, peek(latest(state), prop))) return
		markChangedES5(state)
		prepareCopy(state)
	}
	state.copy![prop] = value
}

export function markChangedES5(state) {
	if (!state.modified) {
		state.modified = true
		if (state.parent) markChangedES5(state.parent)
	}
}

// TODO: kill export
function prepareCopy(state) {
	if (!state.copy) state.copy = clonePotentialDraft(state.base)
}

function clonePotentialDraft(base) {
	const state = base && base[DRAFT_STATE]
	if (state) {
		state.finalizing = true
		const draft = shallowCopy(state.draft, true)
		state.finalizing = false
		return draft
	}
	return shallowCopy(base)
}

// property descriptors are recycled to make sure we don't create a get and set closure per property,
// but share them all instead
const descriptors = {}

function proxyProperty(draft, prop, enumerable) {
	let desc = descriptors[prop]
	if (desc) {
		desc.enumerable = enumerable
	} else {
		descriptors[prop] = desc = {
			configurable: true,
			enumerable,
			get() {
				return get(this[DRAFT_STATE], prop)
			},
			set(value) {
				set(this[DRAFT_STATE], prop, value)
			}
		}
	}
