        : subscribe(dispatch)
      // Only resubscribe to the store when changing selector from function to
      // undefined or undefined to function
    }, [!selector])

    return stateSlice
  }

  let api = { destroy, getState, setState, subscribe }
  let state = createState(setState, getState, api)

  return [useStore, api]
