 * Multipart requests are persisted and decoded as multipart data; other form
 * requests are decoded from URL-encoded body parameters.
 *
 * @stability unstable
 * @category schemas
 * @since 4.0.0
 */
export const schemaBodyForm = <A, I extends Partial<Multipart.Persisted>, RD>(
