      yield* Client.make({
        driver: "mysql2",
        acquirer: Effect.succeed(poolConnection),
        transactionAcquirer,
        releaseSavepoint: (name) => `RELEASE SAVEPOINT ${name}`,
        compiler,
        spanAttributes,
        transformRows
      }),
      { [TypeId]: TypeId as TypeId, config: options }
    )
